<?php namespace App\Repositories\MongoDB; use App\Repositories\Interfaces\ProjectRepositoryInterface; use MongoDB\BSON\UTCDateTime;
final class MongoProjectRepository extends MongoRepository implements ProjectRepositoryInterface { private function c(){return $this->db->db()->projects;} public function all():array{return $this->rows($this->c()->find([],['sort'=>['created_at'=>-1]]));} public function featured(int $l=3):array{return $this->rows($this->c()->find(['featured'=>true],['sort'=>['created_at'=>-1],'limit'=>$l]));} public function find(string $id):?array{$x=$this->c()->findOne(['_id'=>$this->id($id)]);return $x?$this->row($x):null;} public function save(array $d,?string $id=null):string{$d['featured']=(bool)$d['featured'];$d['updated_at']=new UTCDateTime();if($id){$this->c()->updateOne(['_id'=>$this->id($id)],['$set'=>$d]);return $id;}$d['created_at']=new UTCDateTime();return (string)$this->c()->insertOne($d)->getInsertedId();} public function delete(string $id):bool{return $this->c()->deleteOne(['_id'=>$this->id($id)])->getDeletedCount()===1;} public function count():int{return $this->c()->countDocuments();} }
